import { CustomTextStyling, SpeechVoice, PlayerId, DialogueText } from '@bloxd';

type DialogueOpts = {
    /** Shown above the line, such as a name. */
    speakerName?: string | CustomTextStyling;
    /** A preset such as "regular" or "gruff", or every synth parameter. Omit for a silent line. */
    voice?: SpeechVoice;
    /** How long the line stays up, counted from when it starts to appear. Defaults to 6 seconds. */
    durationMs?: number;
};
/**
 * Shows a player a line of dialogue below the crosshair for a while. A new line replaces the one already up.
 * @param playerId - The player to show the line to
 * @param text - The line. `[[Item Name]]` shows the item's icon inline
 * @param opts - The speaker's name, the voice that reads it out, and how long it stays up
 */
declare function sayDialogue(playerId: PlayerId, text: DialogueText, opts?: DialogueOpts): void;
/**
 * Hides the line of dialogue a player is shown.
 * @param playerId - The player shown the line
 */
declare function clearDialogue(playerId: PlayerId): void;

export { clearDialogue, sayDialogue };
export type { DialogueOpts };
